<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientFrontChannelLogoutSessionRequiredAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientFrontChannelLogoutSessionRequiredAccessor trait.
 *
 * Covers null default, string/VO assignment via withFrontChannelLogoutSessionRequired,
 * getFrontChannelLogoutSessionRequired/frontChannelLogoutSessionRequired accessors, and isFrontChannelLogoutSessionRequiredChanged with/without original.
 */
class TrustedClientFrontChannelLogoutSessionRequiredAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withFrontChannelLogoutSessionRequired creates a new instance with the FrontChannelLogoutSessionRequired set
     * from a string value, and getFrontChannelLogoutSessionRequired returns the primitive string.
     */
    public function testWithFrontChannelLogoutSessionRequiredFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientFrontChannelLogoutSessionRequiredAccessorUnitTest();

        // Act
        $result = $holder->withFrontChannelLogoutSessionRequired(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isFrontChannelLogoutSessionRequired());
    }
    /**
     * Asserts that withfrontChannelLogoutSessionRequired has access to the value object
     * from a string value, and getFrontChannelLogoutSessionRequired returns the primitive string.
     */
    public function testWithFrontChannelLogoutSessionRequiredFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientFrontChannelLogoutSessionRequiredAccessorUnitTest();

        // Act
        $result = $holder->withFrontChannelLogoutSessionRequired(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->frontChannelLogoutSessionRequired()->value());
    }
    public function testChangedFrontChannelLogoutSessionRequired(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientFrontChannelLogoutSessionRequiredAccessorUnitTest();
        $original = $holder->withFrontChannelLogoutSessionRequired(true);
        $same = $holder->withFrontChannelLogoutSessionRequired(true);
        $modified = $holder->withFrontChannelLogoutSessionRequired(false);

        // Act
        $unchanged = $holder->isFrontChannelLogoutSessionRequiredChanged();
        $withSame = $original->isFrontChannelLogoutSessionRequiredChanged($same);
        $withDiferent = $original->isFrontChannelLogoutSessionRequiredChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientFrontChannelLogoutSessionRequiredAccessorUnitTest
{
    use TrustedClientFrontChannelLogoutSessionRequiredAccessor;
}
